type Token = { kind: "text" | "tag"; value: string; line: number; column: number };
type Node =
  | { kind: "text"; value: string }
  | { kind: "interpolation"; path: string; escaped: boolean; line: number; column: number }
  | { kind: "comment" }
  | { kind: "block"; name: "if" | "each"; path: string; yes: Node[]; no: Node[]; line: number; column: number };

type Scope = { value: unknown; index?: number; parent?: Scope };

function location(line: number, column: number): string {
  return ` at line ${line}, column ${column}`;
}

function tokenize(template: string): Token[] {
  const tokens: Token[] = [];
  let offset = 0;
  let line = 1;
  let column = 1;
  const advance = (text: string) => {
    const parts = text.split("\n");
    if (parts.length > 1) { line += parts.length - 1; column = parts[parts.length - 1].length + 1; }
    else column += text.length;
  };
  while (offset < template.length) {
    const start = template.indexOf("{{", offset);
    if (start < 0) { tokens.push({ kind: "text", value: template.slice(offset), line, column }); break; }
    if (start > offset) { const text = template.slice(offset, start); tokens.push({ kind: "text", value: text, line, column }); advance(text); }
    const tagLine = line, tagColumn = column;
    const triple = template.startsWith("{{{", start);
    const endMarker = triple ? "}}}" : "}}";
    const end = template.indexOf(endMarker, start + (triple ? 3 : 2));
    if (end < 0) throw new Error(`Unclosed tag${location(tagLine, tagColumn)}`);
    const value = template.slice(start + (triple ? 3 : 2), end).trim();
    const full = template.slice(start, end + endMarker.length);
    tokens.push({ kind: "tag", value: triple ? `{${value}}` : value, line: tagLine, column: tagColumn });
    advance(full); offset = end + endMarker.length;
  }
  return tokens;
}

function parse(template: string): Node[] {
  const tokens = tokenize(template);
  let position = 0;
  const parseList = (closing?: string): { nodes: Node[]; close?: string } => {
    const nodes: Node[] = [];
    while (position < tokens.length) {
      const token = tokens[position++];
      if (token.kind === "text") { nodes.push({ kind: "text", value: token.value }); continue; }
      const tag = token.value;
      if (tag.startsWith("/")) return { nodes, close: tag.slice(1).trim() };
      if (tag === "else") return { nodes, close: "else" };
      if (tag.startsWith("!")) { nodes.push({ kind: "comment" }); continue; }
      if (tag.startsWith("#")) {
        const match = tag.match(/^#(if|each)(?:\s+(.+?))?$/);
        if (!match || !match[2]) throw new Error(`Invalid or unknown block${location(token.line, token.column)}`);
        const name = match[1] as "if" | "each";
        const body = parseList(name);
        if (!body.close) throw new Error(`Unclosed ${name} block${location(token.line, token.column)}`);
        let no: Node[] = [];
        if (body.close === "else") {
          const alternate = parseList(name);
          if (!alternate.close) throw new Error(`Unclosed ${name} block${location(token.line, token.column)}`);
          if (alternate.close === "else") throw new Error(`Duplicate else${location(token.line, token.column)}`);
          if (alternate.close !== name) throw new Error(`Mismatched closing block: expected /${name}, got /${alternate.close}${location(token.line, token.column)}`);
          no = alternate.nodes;
        } else if (body.close !== name) {
          throw new Error(`Mismatched closing block: expected /${name}, got /${body.close}${location(token.line, token.column)}`);
        }
        nodes.push({ kind: "block", name, path: match[2].trim(), yes: body.nodes, no, line: token.line, column: token.column });
        continue;
      }
      if (tag.startsWith("{\n") || tag.startsWith("{")) {
        if (!tag.endsWith("}")) throw new Error(`Invalid unescaped interpolation${location(token.line, token.column)}`);
        nodes.push({ kind: "interpolation", path: tag.slice(1, -1).trim(), escaped: false, line: token.line, column: token.column });
      } else {
        nodes.push({ kind: "interpolation", path: tag, escaped: true, line: token.line, column: token.column });
      }
    }
    if (closing) throw new Error(`Unclosed ${closing} block`);
    return { nodes };
  };
  const result = parseList();
  if (result.close) throw new Error(`${result.close === "else" ? "else outside a block" : `Unexpected closing block /${result.close}`} at line 1, column 1`);
  return result.nodes;
}

function lookup(path: string, scope: Scope, root: unknown): unknown {
  if (path === "this") return scope.value;
  if (path === "@index") { for (let current: Scope | undefined = scope; current; current = current.parent) if (current.index !== undefined) return current.index; return undefined; }
  const thisPath = path === "this" ? [] : path.startsWith("this.") ? path.slice(5).split(".").filter(Boolean) : path.split(".").filter(Boolean);
  const parts = thisPath;
  if (!parts.length) return undefined;
  const read = (base: unknown): unknown => {
    let current = base;
    for (const part of parts) {
      if (current === null || current === undefined || (typeof current !== "object" && typeof current !== "function")) return undefined;
      current = (current as Record<string, unknown>)[part];
    }
    return current;
  };
  for (let current: Scope | undefined = scope; current; current = current.parent) { const value = read(current.value); if (value !== undefined) return value; }
  return read(root);
}

function truthy(value: unknown): boolean { return !(value === undefined || value === null || value === false || value === 0 || value === "" || (Array.isArray(value) && value.length === 0)); }
function scalar(value: unknown, node: { line: number; column: number }): string {
  if (value === undefined || value === null) return "";
  if (typeof value === "object" || typeof value === "function" || typeof value === "symbol") throw new Error(`Cannot render ${typeof value} as scalar${location(node.line, node.column)}`);
  return String(value);
}
function escapeHtml(value: string): string { return value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;"); }

function renderNodes(nodes: Node[], scope: Scope, root: unknown): string {
  let output = "";
  for (const node of nodes) {
    if (node.kind === "text") output += node.value;
    else if (node.kind === "interpolation") { const value = scalar(lookup(node.path, scope, root), node); output += node.escaped ? escapeHtml(value) : value; }
    else if (node.kind === "block") {
      const value = lookup(node.path, scope, root);
      if (node.name === "if") output += renderNodes(truthy(value) ? node.yes : node.no, scope, root);
      else if (Array.isArray(value)) output += value.length ? value.map((item, index) => renderNodes(node.yes, { value: item, index, parent: scope }, root)).join("") : renderNodes(node.no, scope, root);
      else throw new Error(`each expects an array${location(node.line, node.column)}`);
    }
  }
  return output;
}

export function render(template: string, data: unknown): string {
  return renderNodes(parse(template), { value: data }, data);
}

