}

function lookup(path: string, scope: Scope, root: unknown): unknown {
  if (path === "this") return scope.value;
  if (path === "@index") { for (let current: Scope | undefined = scope; current; current = current.parent) if (current.index !== undefined) return current.index; return undefined; }
  const thisPath = path === "this" ? [] : path.startsWith("this.") ? path.slice(5).split(".").filter(Boolean) : path.split(".").filter(Boolean);
  const parts = thisPath;
  if (!parts.length) return undefined;
