}
import { expect, test } from "bun:test";
import { render } from "./engine";

test("interpolates and escapes", () => expect(render("{{x}}|{{{x}}}", { x: "<&>\"'" })).toBe("&lt;&amp;&gt;&quot;&#39;|<&>\"'"));
test("if and nested each", () => expect(render("{{#if ok}}Y{{else}}N{{/if}} {{#each xs}}{{@index}}={{this}}/{{name}};{{/each}}", { ok: 1, xs: ["a", "b"], name: "root" })).toBe("Y 0=a/root;1=b/root;"));
test("comments and whitespace", () => expect(render("a {{! hidden }} b", {})).toBe("a  b"));
test("structural errors include location", () => expect(() => render("{{else}}", {})).toThrow(/line 1, column/));
test("objects cannot be rendered as scalars", () => expect(() => render("{{x}}", { x: {} })).toThrow(/Cannot render/));
# Mini Template

Dependency-free TypeScript template renderer for Bun.

```ts
import { render } from "./src/engine";
render("Hello, {{name}}!", { name: "Ada & Bob" });
```

Use `{{path}}` for escaped values, `{{{path}}}` for raw values, `{{#if path}}...{{else}}...{{/if}}`, and `{{#each items}}...{{/each}}`. Inside `each`, `{{this}}` and `{{@index}}` are available. The CLI is `bun run src/cli.ts TEMPLATE_FILE DATA.json`.

